class Solution {
public:
    bool canMakeSquare(vector<vector<char>>& grid) {
        for (int r = 0; r < 2; ++r) {
            for (int c = 0; c < 2; ++c) {
                int black = 0;
                for (int dr = 0; dr < 2; ++dr) {
                    for (int dc = 0; dc < 2; ++dc) {
                        if (grid[r + dr][c + dc] == 'B') black++;
                    }
                }
                if (black != 2) return true;
            }
        }
        return false;
    }
};

class Solution {
    public boolean canMakeSquare(char[][] grid) {
        for (int r = 0; r < 2; r++) {
            for (int c = 0; c < 2; c++) {
                int black = 0;
                for (int dr = 0; dr < 2; dr++) {
                    for (int dc = 0; dc < 2; dc++) {
                        if (grid[r + dr][c + dc] == 'B') black++;
                    }
                }
                if (black != 2) return true;
            }
        }
        return false;
    }
}

